"""Week 9 Day 3 as eight ```story blocks (rebuild once with rebuild.py w9d3, then apply.py w9d3), English and Russian from one source.
Every number is on the page or computed from data/raw/nur.db (7 615 scored loans, 223 bads; the toy is 20 loans: 5 bads, 15 goods)."""
from common import build as _b, btn
from w9data import FROM, N, B

TG = [560, 600, 620, 630, 650, 660, 670, 680, 710, 720, 730, 740, 750, 770, 790]   # the toy's 15 goods
TB = [540, 580, 610, 640, 700]                                                   # and its 5 bads: AUC 60 / 75 = 0.80
# every roc picture names all its options, so a step that switches toy <-> real starts clean (shows merge within a kind)
BASE = {"kind": "roc", "left": "dist", "cut": None, "cm": False, "rates": False, "acc": False, "appr": False, "roc": False, "curve": None,
        "area": False, "ks": False, "corners": False, "drag": False, "gini": False}
TOY = dict(BASE, goods=TG, bads=TB, n=None, b=None, lo=520, hi=800)
REAL = dict(BASE, n=N, b=B, goods=None, bads=None, **{"from": FROM}, lo=500, hi=800)
DEC_N = [762] * 5 + [761] * 5
DEC_B = [56, 37, 38, 25, 12, 12, 16, 15, 6, 6]


def nudge(by, rep=1):
    lab = ("+%d" % by) if by > 0 else ("−%d" % -by)
    return btn(0, lab, lab, rep, do="nudge", by=by)


def toy(**kw):
    d = dict(TOY); d.update(kw); return d


def real(**kw):
    d = dict(REAL); d.update(kw); return d


